  `best_val_loss` float DEFAULT NULL COMMENT '最佳验证损失',
  `convergence_epoch` int DEFAULT NULL COMMENT '收敛轮次',
  `train_metrics` text COLLATE utf8mb4_unicode_ci COMMENT '训练指标 JSON字符串',
  `validation_metrics` text COLLATE utf8mb4_unicode_ci COMMENT '验证指标 JSON字符串',
