  `parameters_count` int DEFAULT NULL COMMENT '参数数量',
  `memory_usage` float DEFAULT NULL COMMENT '内存使用量（MB）',
  `gpu_usage` float DEFAULT NULL COMMENT 'GPU使用率',
  `cpu_usage` float DEFAULT NULL COMMENT 'CPU使用率',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'running' COMMENT '状态: running, completed, failed',
  `logs` text COLLATE utf8mb4_unicode_ci COMMENT '训练日志',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_model_id` (`model_id`),
  KEY `idx_status` (`status`),
  KEY `idx_start_time` (`start_time`),
